package session

import (
	"github.com/jeremyhahn/go-libsignal/pkg/util/crypto"
	"github.com/jeremyhahn/go-libsignal/pkg/util/crypto/secret"
)

// secretAlloc is the function used to allocate guarded secrets. It defaults to
// secret.New and may be replaced in tests to simulate allocation failures.
var secretAlloc = secret.New

// NewDerivedSecrets returns a new RootKey/ChainKey/InitialPQRKey triple from 96 bytes
// of key material generated by the key derivation function. Each 32-byte segment is
// moved into locked memory. The source keyMaterial slice is zeroized after
// splitting. Panics if locked-memory allocation fails (fatal condition).
//
// This matches the Rust derive_keys which returns (RootKey, ChainKey, InitialPQRKey).
func NewDerivedSecrets(keyMaterial []byte) *DerivedSecrets {
	rootKeyBytes := make([]byte, 32)
	chainKeyBytes := make([]byte, 32)
	copy(rootKeyBytes, keyMaterial[:32])
	copy(chainKeyBytes, keyMaterial[32:64])

	// Extract the third 32-byte segment for the InitialPQRKey if present.
	var pqrKeyBytes []byte
	if len(keyMaterial) >= 96 {
		pqrKeyBytes = make([]byte, 32)
		copy(pqrKeyBytes, keyMaterial[64:96])
	}
	crypto.Zeroize(keyMaterial)

	guardedRoot, err := secretAlloc(rootKeyBytes)
	if err != nil {
		panic("session: failed to allocate guarded memory for root key: " + err.Error())
	}
	guardedChain, err := secretAlloc(chainKeyBytes)
	if err != nil {
		guardedRoot.Destroy()
		panic("session: failed to allocate guarded memory for chain key: " + err.Error())
	}

	var guardedPQR *secret.Secret
	if pqrKeyBytes != nil {
		guardedPQR, err = secretAlloc(pqrKeyBytes)
		if err != nil {
			guardedRoot.Destroy()
			guardedChain.Destroy()
			panic("session: failed to allocate guarded memory for PQR key: " + err.Error())
		}
	}

	return &DerivedSecrets{
		rootKey:  guardedRoot,
		chainKey: guardedChain,
		pqrKey:   guardedPQR,
	}
}

// DerivedSecrets is a structure for holding the derived secrets for the
// Root, Chain, and InitialPQR keys for a session. Key material is stored in
// locked memory.
type DerivedSecrets struct {
	rootKey  *secret.Secret
	chainKey *secret.Secret
	pqrKey   *secret.Secret
}

// RootKey returns the RootKey bytes as a view into guarded memory.
// The returned slice must not be retained beyond the lifetime of this DerivedSecrets.
func (d *DerivedSecrets) RootKey() []byte {
	return d.rootKey.Bytes()
}

// ChainKey returns the ChainKey bytes as a view into guarded memory.
// The returned slice must not be retained beyond the lifetime of this DerivedSecrets.
func (d *DerivedSecrets) ChainKey() []byte {
	return d.chainKey.Bytes()
}

// InitialPQRKey returns the InitialPQRKey bytes as a view into guarded memory,
// or nil if no PQR key was derived (e.g., for legacy 64-byte derivations).
// The returned slice must not be retained beyond the lifetime of this DerivedSecrets.
func (d *DerivedSecrets) InitialPQRKey() []byte {
	if d.pqrKey == nil {
		return nil
	}
	return d.pqrKey.Bytes()
}

// Zeroize destroys the guarded memory holding the derived secrets.
// This method is idempotent and safe to call multiple times.
func (d *DerivedSecrets) Zeroize() {
	if d.rootKey != nil {
		d.rootKey.Destroy()
	}
	if d.chainKey != nil {
		d.chainKey.Destroy()
	}
	if d.pqrKey != nil {
		d.pqrKey.Destroy()
	}
}
